description:
Show active users on the page

## Requirements
- Show active users on each page
- Real-time presence updates
- Display user avatars/names
- Show when users join/leave

## Technical Context
Implement a user presence system to show which users are currently active on the page.

## Implementation Steps

### 1. Backend WebSocket Presence Tracking
**File:** /home/seethbotsite/backend/src/websocket/presence.js (create)

```javascript
// Track users per page/room
const presenceStore = new Map();
// Structure: { "/home": { userId1: { name, avatar, lastSeen }, userId2: {...} }, "/movies": {...} }

function handleJoin(ws, data) {
  const { userId, userName, userAvatar, page } = data;

  if (!presenceStore.has(page)) {
    presenceStore.set(page, new Map());
  }

  presenceStore.get(page).set(userId, {
    name: userName,
    avatar: userAvatar,
    lastSeen: Date.now()
  });

  // Broadcast join to all users on page
  broadcastToPage(page, {
    type: "presence-join",
    user: { id: userId, name: userName, avatar: userAvatar }
  });
}

function handleLeave(ws, data) {
  const { userId, page } = data;

  if (presenceStore.has(page)) {
    presenceStore.get(page).delete(userId);

    // Broadcast leave to all users on page
    broadcastToPage(page, {
      type: "presence-leave",
      userId
    });
  }
}

function handleHeartbeat(ws, data) {
  const { userId, page } = data;

  if (presenceStore.has(page)) {
    const users = presenceStore.get(page);
    if (users.has(userId)) {
      users.get(userId).lastSeen = Date.now();
    }
  }
}

// Cleanup inactive users (run every 30 seconds)
setInterval(() => {
  const now = Date.now();
  const timeout = 2 * 60 * 1000; // 2 minutes

  presenceStore.forEach((users, page) => {
    users.forEach((user, userId) => {
      if (now - user.lastSeen > timeout) {
        users.delete(userId);
        broadcastToPage(page, {
          type: "presence-leave",
          userId
        });
      }
    });
  });
}, 30000);
```

