<template>
  <div class="active-users-panel">
    <div class="panel-header">
      <span class="panel-title">Active Users</span>
      <span class="user-count">{{ activeUsers.length }}</span>
    </div>
    <div class="user-list">
      <div
        v-for="user in activeUsers"
        :key="user.id"
        class="user-item"
        :class="{ joining: user.isJoining, leaving: user.isLeaving }"
      >
        <img :src="user.avatar" :alt="user.name" class="user-avatar" />
        <span class="user-name">{{ user.name }}</span>
      </div>
      <div v-if="activeUsers.length === 0" class="no-users">
        No active users
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, onUnmounted } from "vue";
import { useRoute } from "vue-router";

const route = useRoute();
const activeUsers = ref([]);
let ws = null;
let heartbeatInterval = null;

function connectWebSocket() {
  ws = new WebSocket("ws://localhost:8081/ws/presence");

  ws.onopen = () => {
    // Join current page
    ws.send(JSON.stringify({
      type: "presence-join",
      userId: getUserId(), // Get from auth store or local storage
      userName: getUserName(),
      userAvatar: getUserAvatar(),
      page: route.path
    }));

    // Start heartbeat
    heartbeatInterval = setInterval(() => {
      ws.send(JSON.stringify({
        type: "presence-heartbeat",
        userId: getUserId(),
        page: route.path
      }));
    }, 30000);
  };

  ws.onmessage = (event) => {
    const message = JSON.parse(event.data);

    switch (message.type) {
      case "presence-join":
        activeUsers.value.push({
          ...message.user,
          isJoining: true
        });
        setTimeout(() => {
          const user = activeUsers.value.find(u => u.id === message.user.id);
          if (user) user.isJoining = false;
        }, 300);
        break;
      case "presence-leave":
        const userIndex = activeUsers.value.findIndex(u => u.id === message.userId);
        if (userIndex !== -1) {
          activeUsers.value[userIndex].isLeaving = true;
          setTimeout(() => {
            activeUsers.value.splice(userIndex, 1);
          }, 300);
        }
        break;
    }
  };

  ws.onclose = () => {
    // Reconnect after 3 seconds
    setTimeout(connectWebSocket, 3000);
  };
}

onMounted(() => {
  connectWebSocket();
});

onUnmounted(() => {
  if (ws) {
    ws.send(JSON.stringify({
      type: "presence-leave",
      userId: getUserId(),
      page: route.path
    }));
    ws.close();
  }
  if (heartbeatInterval) {
    clearInterval(heartbeatInterval);
  }
});

function getUserId() {
  // TODO: Get from auth store when #133 is implemented
  return localStorage.getItem("user_id") || "guest";
}

function getUserName() {
  // TODO: Get from auth store when #133 is implemented
  return localStorage.getItem("user_name") || "Guest";
}

function getUserAvatar() {
  // TODO: Get from auth store when #133 is implemented
  return localStorage.getItem("user_avatar") || "/default-avatar.png";
}
</script>

